            pw.println("Call graph nodes: " + cgNodes);
            pw.println("Call graph edges: " + cgEdges);
            pw.println();
            pw.println("--- Call Graph Analysis (RTA - Rapid Type Analysis) ---");
            pw.println("RTA call graph nodes: " + rtaNodes);
            pw.println("RTA call graph edges: " + rtaEdges);
            pw.println();
            pw.println("--- Pointer Analysis ---");
            pw.println("Pointer analysis: Completed (0-CFA)");
            pw.println("Pointer keys: " + pa.getPointerKeys().size());
            pw.println();
            pw.println("--- Analysis Parameters ---");
            pw.println("Call graph algorithm: 0-CFA (zero-container context-sensitive)");
            pw.println("Entry points: main() methods in application classes");
            pw.println("Exclusions: AWT, javax, sun, com.sun, java.lang.invoke, tika.fork");
        }
        System.out.println("Written: wala-analysis-summary.txt");
    }

    private static void writeCallGraph(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph-0cfa.txt"))) {
            pw.println("=== WALA Call Graph (0-CFA) for Apache Tika ===");
            pw.println("Nodes: " + cg.getNumberOfNodes());
            pw.println();
