                pw.println("NODE: " + node.getMethod().getSignature());
                pw.println("  Context: " + node.getContext());
                for (CGNode succ : cg) {
                    if (cg.hasEdge(node, succ)) {
                        pw.println("  -> " + succ.getMethod().getSignature());
                    }
                }
            }
        }
        System.out.println("Written: wala-callgraph-0cfa.txt");
    }

    private static void writeRTACallGraph(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph-rta.txt"))) {
