    private static void writeClassHierarchySummary(File outputDir, ClassHierarchy cha) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-class-hierarchy.txt"))) {
            pw.println("=== Class Hierarchy Summary - Apache Tika ===");
            pw.println("Total classes: " + cha.getNumberOfClasses());
            pw.println();

            List<String> appClasses = new ArrayList<>();
            cha.forEach(klass -> {
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appClasses.add(klass.getName().toString());
                }
            });
            Collections.sort(appClasses);

            pw.println("--- Application Classes ---");
            for (String cls : appClasses) {
                pw.println(cls);
            }

            pw.println();
            pw.println("--- Interface Implementations ---");
            cha.forEach(klass -> {
                if (klass.isInterface() && 
                    klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    pw.println("Interface: " + klass.getName());
                    for (var impl : cha.getImplementors(klass.getReference())) {
                        pw.println("  implements: " + impl.getName());
                    }
                }
            });
        }
        System.out.println("Written: wala-class-hierarchy.txt");
    }

    private static void writeDotGraph(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph.dot"))) {
            pw.println("digraph CallGraph {");
            pw.println("  rankdir=LR;");
            pw.println("  node [shape=box, fontname=\"Helvetica\", fontsize=10];");
            pw.println("  edge [fontname=\"Helvetica\", fontsize=8];");
            pw.println();

            // Only include application nodes for readability
            Map<CGNode, String> nodeIds = new HashMap<>();
            int id = 0;
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    String nodeId = "n" + (id++);
                    nodeIds.put(node, nodeId);
                    String label = node.getMethod().getDeclaringClass().getName().toString()
                        .replace("/", ".") + "." + node.getMethod().getName().toString();
                    pw.println("  " + nodeId + " [label=\"" + escapeDot(label) + "\"];");
                }
            }

            pw.println();
            for (CGNode src : nodeIds.keySet()) {
                for (CGNode dst : nodeIds.keySet()) {
                    if (cg.hasEdge(src, dst)) {
                        pw.println("  " + nodeIds.get(src) + " -> " + nodeIds.get(dst) + ";");
                    }
                }
            }
            pw.println("}");
        }
        System.out.println("Written: wala-callgraph.dot");
    }

    private static String escapeDot(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
