package com.ibm.wala.analysis;

import com.ibm.wala.classLoader.JavaLanguage;
import com.ibm.wala.classLoader.Language;
import com.ibm.wala.ipa.callgraph.*;
import com.ibm.wala.ipa.callgraph.impl.Util;
import com.ibm.wala.ipa.callgraph.propagation.InstanceKey;
import com.ibm.wala.ipa.callgraph.propagation.PointerAnalysis;
import com.ibm.wala.ipa.cha.ClassHierarchy;
import com.ibm.wala.ipa.cha.ClassHierarchyFactory;
import com.ibm.wala.core.util.config.AnalysisScopeReader;
import com.ibm.wala.types.ClassLoaderReference;
import com.ibm.wala.util.CancelException;

import java.io.*;
import java.util.*;

/**
 * WALA static analysis of Apache Tika.
 * Performs call graph construction and pointer analysis on tika-core.
 */
public class TikaAnalysis {

    static final String OUTPUT_DIR = System.getProperty("output.dir", "/analysis-results");

    public static void main(String[] args) throws Exception {
        String appJar = args.length > 0 ? args[0] : "/workspace/tika-core.jar";

        File outputDir = new File(OUTPUT_DIR);
        outputDir.mkdirs();

        System.out.println("=== WALA Static Analysis of Apache Tika ===");
        System.out.println("Target JAR: " + appJar);
        System.out.println("Output Directory: " + OUTPUT_DIR);
        System.out.println();

        // Create analysis scope
        File exclusionFile = createExclusionFile();
        AnalysisScope scope = AnalysisScopeReader.instance.makeJavaBinaryAnalysisScope(appJar, exclusionFile);

        // Build class hierarchy
        System.out.println("Building class hierarchy...");
        ClassHierarchy cha = ClassHierarchyFactory.make(scope);

        int classCount = cha.getNumberOfClasses();
        System.out.println("Class hierarchy built. Total classes: " + classCount);

        // Collect application classes
        List<String> appClasses = new ArrayList<>();
        cha.forEach(klass -> {
            if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                appClasses.add(klass.getName().toString());
            }
        });
        Collections.sort(appClasses);

        System.out.println("Application classes: " + appClasses.size());

        // Create entrypoints - use all main() methods in application classes
        Iterable<Entrypoint> entrypoints = Util.makeMainEntrypoints(cha);

        AnalysisOptions options = new AnalysisOptions(scope, entrypoints);
        AnalysisCache cache = new AnalysisCacheImpl();

        // ===== Build Call Graph using 0-CFA (context-insensitive) =====
        System.out.println("\n=== Building Call Graph (0-CFA) ===");
        CallGraphBuilder<InstanceKey> builder = 
            Util.makeZeroCFABuilder(JavaLanguage.get(), options, cache, cha);

        CallGraph cg;
        try {
            cg = builder.makeCallGraph(options, null);
        } catch (CancelException e) {
            throw new RuntimeException(e);
        }

        // Collect call graph statistics
        int nodeCount = cg.getNumberOfNodes();
        int edgeCount = 0;
        for (CGNode node : cg) {
            edgeCount += cg.getSuccNodeCount(node);
        }

        System.out.println("Call graph nodes: " + nodeCount);
        System.out.println("Call graph edges: " + edgeCount);

        // ===== Build Call Graph using RTA (Rapid Type Analysis) =====
        System.out.println("\n=== Building Call Graph (RTA) ===");
        AnalysisOptions rtaOptions = new AnalysisOptions(scope, entrypoints);
        AnalysisCache rtaCache = new AnalysisCacheImpl();
        CallGraphBuilder<InstanceKey> rtaBuilder =
            Util.makeRTABuilder(rtaOptions, rtaCache, cha);

        CallGraph rtaCg;
        try {
            rtaCg = rtaBuilder.makeCallGraph(rtaOptions, null);
        } catch (CancelException e) {
            throw new RuntimeException(e);
        }

        int rtaNodeCount = rtaCg.getNumberOfNodes();
        int rtaEdgeCount = 0;
        for (CGNode node : rtaCg) {
            rtaEdgeCount += rtaCg.getSuccNodeCount(node);
        }
        System.out.println("RTA Call graph nodes: " + rtaNodeCount);
        System.out.println("RTA Call graph edges: " + rtaEdgeCount);

        // ===== Pointer Analysis =====
        System.out.println("\n=== Pointer Analysis ===");
        PointerAnalysis<InstanceKey> pa = builder.getPointerAnalysis();
        int pointerKeyCount = 0;
        for (var pk : pa.getPointerKeys()) {
            pointerKeyCount++;
        }
        System.out.println("Pointer analysis completed. Pointer keys: " + pointerKeyCount);

        // ===== Write Results =====
        writeSummary(outputDir, classCount, appClasses.size(), 
                     nodeCount, edgeCount, rtaNodeCount, rtaEdgeCount, pointerKeyCount);
        writeCallGraph(outputDir, cg, "0cfa");
        writeCallGraph(outputDir, rtaCg, "rta");
        writeApplicationClasses(outputDir, appClasses);
        writeCallGraphEdges(outputDir, cg);
        writePointerAnalysis(outputDir, cg, pa, pointerKeyCount);
        writeReachableMethods(outputDir, cg);
        writeClassHierarchySummary(outputDir, cha);
        writeDotGraph(outputDir, cg);

        System.out.println("\n=== Analysis Complete ===");
        System.out.println("Results saved to: " + OUTPUT_DIR);
    }

    private static File createExclusionFile() throws IOException {
        File f = File.createTempFile("wala-exclusions", ".txt");
        try (PrintWriter pw = new PrintWriter(f)) {
            pw.println("java/awt/.*");
            pw.println("javax/.*");
            pw.println("sun/.*");
            pw.println("com/sun/.*");
            pw.println("java/lang/invoke/.*");
            pw.println("org/apache/tika/fork/.*");
        }
        return f;
    }

    private static void writeSummary(File outputDir, int classCount, int appClassCount,
            int cgNodes, int cgEdges, int rtaNodes, int rtaEdges, int pointerKeyCount) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-analysis-summary.txt"))) {
            pw.println("=== WALA Static Analysis Summary for Apache Tika ===");
            pw.println("Analysis Tool: WALA (T. J. Watson Libraries for Analysis)");
            pw.println("Target Project: Apache Tika (tika-core module)");
            pw.println("Analysis Date: " + new Date());
            pw.println();
            pw.println("--- Class Hierarchy ---");
            pw.println("Total classes in scope: " + classCount);
            pw.println("Application classes: " + appClassCount);
            pw.println();
            pw.println("--- Call Graph Analysis (0-CFA, Context-Insensitive) ---");
            pw.println("Call graph nodes: " + cgNodes);
            pw.println("Call graph edges: " + cgEdges);
            pw.println();
            pw.println("--- Call Graph Analysis (RTA - Rapid Type Analysis) ---");
            pw.println("RTA call graph nodes: " + rtaNodes);
            pw.println("RTA call graph edges: " + rtaEdges);
            pw.println();
            pw.println("--- Pointer Analysis ---");
            pw.println("Pointer analysis: Completed (0-CFA)");
            pw.println("Pointer keys: " + pointerKeyCount);
            pw.println();
            pw.println("--- Analysis Parameters ---");
            pw.println("Call graph algorithm: 0-CFA (zero-container context-sensitive)");
            pw.println("Entry points: main() methods in application classes");
            pw.println("Exclusions: AWT, javax, sun, com.sun, java.lang.invoke, tika.fork");
        }
        System.out.println("Written: wala-analysis-summary.txt");
    }

