            pw.println("--- Pointer Analysis ---");
            pw.println("Pointer analysis: Completed (0-CFA)");
            pw.println("Pointer keys: " + pointerKeyCount);
            pw.println();
            pw.println("--- Analysis Parameters ---");
            pw.println("Call graph algorithm: 0-CFA (zero-container context-sensitive)");
            pw.println("Entry points: All public non-abstract methods in application classes");
            pw.println("Exclusions: AWT, javax, sun, com.sun, java.lang.invoke, tika.fork, jdk");
        }
        System.out.println("Written: wala-analysis-summary.txt");
    }

    private static void writeCallGraph(File outputDir, CallGraph cg, String suffix) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph-" + suffix + ".txt"))) {
            pw.println("=== WALA Call Graph (" + suffix.toUpperCase() + ") for Apache Tika ===");
            pw.println("Nodes: " + cg.getNumberOfNodes());
            pw.println();
            for (CGNode node : cg) {
                pw.println("NODE: " + node.getMethod().getSignature());
                pw.println("  Context: " + node.getContext());
                for (Iterator<CGNode> it = cg.getSuccNodes(node); it.hasNext(); ) {
                    CGNode succ = it.next();
                    pw.println("  -> " + succ.getMethod().getSignature());
                }
            }
        }
        System.out.println("Written: wala-callgraph-" + suffix + ".txt");
    }

    private static void writeApplicationClasses(File outputDir, List<String> appClasses) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-application-classes.txt"))) {
            pw.println("=== Application Classes in Apache Tika (tika-core) ===");
            pw.println("Total: " + appClasses.size());
            pw.println();
            for (String cls : appClasses) {
                pw.println(cls);
            }
        }
        System.out.println("Written: wala-application-classes.txt");
    }

    private static void writeCallGraphEdges(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph-edges.txt"))) {
            pw.println("# WALA Call Graph Edges (0-CFA) - Apache Tika");
            pw.println("# Format: source_method -> target_method");
            pw.println();
            int edgeCount = 0;
            for (CGNode node : cg) {
                for (Iterator<CGNode> it = cg.getSuccNodes(node); it.hasNext(); ) {
                    CGNode succ = it.next();
                    pw.println(node.getMethod().getSignature() + " -> " + succ.getMethod().getSignature());
                    edgeCount++;
                }
            }
            pw.println("# Total edges: " + edgeCount);
        }
        System.out.println("Written: wala-callgraph-edges.txt");
    }

    private static void writePointerAnalysis(File outputDir, CallGraph cg, 
            PointerAnalysis<InstanceKey> pa, int pointerKeyCount) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-pointer-analysis.txt"))) {
            pw.println("=== WALA Pointer Analysis for Apache Tika ===");
            pw.println("Pointer keys: " + pointerKeyCount);
            pw.println();

            int count = 0;
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    pw.println("Method: " + node.getMethod().getSignature());
                    count++;
                    if (count > 200) {
                        pw.println("... (truncated for brevity)");
                        break;
                    }
                }
            }
        }
        System.out.println("Written: wala-pointer-analysis.txt");
    }

    private static void writeReachableMethods(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-reachable-methods.txt"))) {
            pw.println("=== Reachable Methods (0-CFA Call Graph) - Apache Tika ===");
            pw.println("Total reachable methods: " + cg.getNumberOfNodes());
            pw.println();

            List<String> methods = new ArrayList<>();
            for (CGNode node : cg) {
                methods.add(node.getMethod().getSignature());
            }
            Collections.sort(methods);
            for (String m : methods) {
                pw.println(m);
            }
        }
        System.out.println("Written: wala-reachable-methods.txt");
    }

    private static void writeClassHierarchySummary(File outputDir, ClassHierarchy cha) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-class-hierarchy.txt"))) {
            pw.println("=== Class Hierarchy Summary - Apache Tika ===");
            pw.println("Total classes: " + cha.getNumberOfClasses());
            pw.println();

            List<String> appClasses = new ArrayList<>();
            cha.forEach(klass -> {
                if (klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    appClasses.add(klass.getName().toString());
                }
            });
            Collections.sort(appClasses);

            pw.println("--- Application Classes ---");
            for (String cls : appClasses) {
                pw.println(cls);
            }

            pw.println();
            pw.println("--- Interface Implementations ---");
            cha.forEach(klass -> {
                if (klass.isInterface() && 
                    klass.getClassLoader().getReference().equals(ClassLoaderReference.Application)) {
                    pw.println("Interface: " + klass.getName());
                    for (var impl : cha.getImplementors(klass.getReference())) {
                        pw.println("  implements: " + impl.getName());
                    }
                }
            });
        }
        System.out.println("Written: wala-class-hierarchy.txt");
    }

    private static void writeDotGraph(File outputDir, CallGraph cg) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-callgraph.dot"))) {
            pw.println("digraph CallGraph {");
            pw.println("  rankdir=LR;");
            pw.println("  node [shape=box, fontname=\"Helvetica\", fontsize=10];");
            pw.println("  edge [fontname=\"Helvetica\", fontsize=8];");
            pw.println();

            // Only include application nodes for readability
            Map<CGNode, String> nodeIds = new HashMap<>();
            int id = 0;
            for (CGNode node : cg) {
                if (node.getMethod().getDeclaringClass().getClassLoader().getReference()
                        .equals(ClassLoaderReference.Application)) {
                    String nodeId = "n" + (id++);
                    nodeIds.put(node, nodeId);
                    String label = node.getMethod().getDeclaringClass().getName().toString()
                        .replace("/", ".") + "." + node.getMethod().getName().toString();
                    pw.println("  " + nodeId + " [label=\"" + escapeDot(label) + "\"];");
                }
            }

            pw.println();
            for (CGNode src : nodeIds.keySet()) {
                for (Iterator<CGNode> it = cg.getSuccNodes(src); it.hasNext(); ) {
                    CGNode dst = it.next();
                    if (nodeIds.containsKey(dst)) {
                        pw.println("  " + nodeIds.get(src) + " -> " + nodeIds.get(dst) + ";");
                    }
                }
            }
            pw.println("}");
        }
        System.out.println("Written: wala-callgraph.dot");
    }

    private static void writeEntrypoints(File outputDir, List<Entrypoint> entrypoints) throws IOException {
        try (PrintWriter pw = new PrintWriter(new File(outputDir, "wala-entrypoints.txt"))) {
            pw.println("=== Entry Points for WALA Analysis ===");
            pw.println("Total entry points: " + entrypoints.size());
            pw.println();
            for (Entrypoint ep : entrypoints) {
                pw.println(ep.getMethod().getSignature());
            }
        }
        System.out.println("Written: wala-entrypoints.txt");
    }

    private static String escapeDot(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}
